B.aKb=new A.a(B.a,["EVITAR intuba\xe7\xe3o tardia, mas realizar com extrema cautela (risco de barotrauma).","EVITAR demorar IOT en agotamiento."],t.w)
B.agM=s(["salbutamol","hidrocortisona","sulfato_magnesio","aminofilina"],t.s)
B.bjf=new A.ax("mal_asmatico_ped",B.aRA,B.aB,B.awE,B.aJ_,B.aKb,B.agM)
