B.aJe=new A.a(B.a,["Hist\xf3rico de v\xf4mito/engasgo + infiltrado em lobos dependentes (base D) + febre + escarro f\xe9tido.","Antecedente de aspiraci\xf3n + infiltrado en zonas dependientes + fiebre."],t.w)
B.alC=s(["1. Antibi\xf3tico com cobertura para anaer\xf3bios: Amoxicilina-Sulbactam ou Clindamicina","2. Higiene oral e eleva\xe7\xe3o da cabeceira","3. Suporte de Oxig\xeanio","4. Avaliar degluti\xe7\xe3o (Fonoaudiologia) p\xf3s-crise"],t.s)
B.atm=s(["1. Antibi\xf3tico: Amox-Sulbactam o Clindamicina","2. Soporte ventilatorio","3. Cabecera elevada","4. Evaluar degluci\xf3n post-crisis"],t.s)
B.b8c=new A.a(B.a,[B.alC,B.atm],t.R)
B.aYt=new A.a(B.a,["EVITAR antibi\xf3ticos profil\xe1ticos em pacientes que aspiraram mas n\xe3o t\xeam pneumonia cl\xednica (apenas vigil\xe2ncia).","EVITAR antibi\xf3ticos profil\xe1cticos tras aspiraci\xf3n simple."],t.w)
B.aq0=s(["amoxicilina_sulbactam","clindamicina"],t.s)
B.biP=new A.ax("pneumonia_aspirativa",B.aVY,B.db,B.aJe,B.b8c,B.aYt,B.aq0)
B.b6i=new A.a(B.a,["Descolamento Prematuro de Placenta (DPP)","Desprendimiento Prematuro de Placenta (DPP)"],t.w)
B.aGC=new A.a(B.a,["Dor abdominal s\xfabita + hipertonia uterina (abdome em t\xe1bua) + sangramento vaginal escuro (80%) + sofrimento fetal.","Dolor abdominal s\xfabito + hiperton\xeda uterina + sangrado vaginal oscuro + sufrimiento fetal."],t.w)
