B.aQb=new A.a(B.a,["S\xedndrome de Abstin\xeancia de Opioides","S\xedndrome de Abstinencia de Opioides"],t.w)
B.aQS=new A.a(B.a,["Midr\xedase, bocejos, rinorreia, piloere\xe7\xe3o, c\xf3licas abdominais, diarreia e ansiedade extrema.","Midriasis, bostezos, rinorrea, piloerecci\xf3n, c\xf3licos, diarrea y ansiedad extrema."],t.w)
B.ahF=s(["1. Clonidina 0.1 mg cada 8h (controle simp\xe1tico)","2. Metadona 10-20 mg VO (reposi\xe7\xe3o escalonada)","3. Loperamida para diarreia","4. Antiem\xe9ticos (Metoclopramida)","5. Suporte de hidrata\xe7\xe3o"],t.s)
B.agB=s(["1. Clonidina 0.1 mg c/8h (control simp\xe1tico)","2. Metadona 10-20 mg VO (reposici\xf3n escalonada)","3. Loperamida para diarrea","4. Antiem\xe9ticos (Metoclopramida)","5. Soporte de hidrataci\xf3n"],t.s)
B.aX_=new A.a(B.a,[B.ahF,B.agB],t.R)
B.bcC=new A.a(B.a,["EVITAR uso de Naloxona (ir\xe1 precipitar ou piorar gravemente os sintomas).","EVITAR Naloxona."],t.w)
